import { DurableObject } from "cloudflare:workers";
import { describeError } from "../errors.ts";
import type { ExtractionParams } from "../workflow/extraction.ts";
import { jobIndexStub } from "./job-index.ts";

interface WaitingRef {
  jobId: string;
  key: string;
}

interface Lease {
  jobId: string;
}

export type EnqueueResult = { created: boolean } | { conflict: true };

const TERMINAL_INSTANCE_STATUSES = new Set(["complete", "errored", "terminated"]);

function waitingKey(seq: number): string {
  return `job:${String(seq).padStart(8, "0")}`;
}

export function domainQueueStub(env: Cloudflare.Env, domain: string) {
  return env.DOMAIN_QUEUE.get(env.DOMAIN_QUEUE.idFromName(domain));
}

// One instance per domain, the only creator of its domain's workflow
// instances: a lease names the running job and waiting jobs sit one storage
// key each (their params carry whole articles, so the FIFO is never rewritten
// as a single value).
export class DomainQueue extends DurableObject<Cloudflare.Env> {
  async enqueue(jobId: string, params: ExtractionParams): Promise<EnqueueResult> {
    let result: EnqueueResult = { created: false };
    let failure: string | null = null;
    try {
      await this.ctx.blockConcurrencyWhile(async () => {
        const stored = await this.ctx.storage.get<unknown>(["lease", "waiting", "seq"]);
        const lease = stored.get("lease") as Lease | undefined;
        const waiting = (stored.get("waiting") as WaitingRef[] | undefined) ?? [];
        if (lease?.jobId === jobId || waiting.some((entry) => entry.jobId === jobId)) {
          result = { conflict: true };
          return;
        }
        // The platform's create() does not reliably reject an existing id
        // locally, so the write-once index is the duplicate check: every id
        // ever enqueued lands there before the create runs.
        if ((await jobIndexStub(this.env).domainOf(jobId)) != null) {
          result = { conflict: true };
          return;
        }
        if (lease == null) {
          // The instance is created before the lease is persisted, both inside
          // this single-threaded window, so a create that throws leaves no
          // lease behind for the alarm to sweep.
          try {
            await this.env.EXTRACTION.create({ id: jobId, params });
          } catch (error) {
            failure = describeError(error);
            return;
          }
          await this.ctx.storage.put("lease", { jobId });
          await this.ctx.storage.setAlarm(Date.now() + this.env.leaseAlarmMs);
          result = { created: true };
        } else {
          const seq = ((stored.get("seq") as number | undefined) ?? 0) + 1;
          const key = waitingKey(seq);
          waiting.push({ jobId, key });
          await this.ctx.storage.put({ [key]: params, seq, waiting });
        }
        // The index entry is awaited before the enqueue replies: an id that
        // has no instance yet stays reachable for the read path.
        await jobIndexStub(this.env).recordEntry(jobId, params.domain);
      });
    } catch (error) {
      failure = describeError(error);
    }
    // Captured inside the critical section (a throw out of it would reset the
    // object), rethrown outside it so the caller sees one failure channel.
    if (failure != null) {
      throw new Error(`creating the workflow failed: ${failure}`);
    }
    return result;
  }

  async release(jobId: string): Promise<void> {
    await this.ctx.blockConcurrencyWhile(async () => {
      const lease = await this.ctx.storage.get<Lease>("lease");
      if (lease?.jobId !== jobId) {
        return;
      }
      await this.ctx.storage.delete("lease");
      await this.advance();
    });
  }

  async stateOf(jobId: string): Promise<"queued" | "running" | "unknown"> {
    const stored = await this.ctx.storage.get<unknown>(["lease", "waiting"]);
    const lease = stored.get("lease") as Lease | undefined;
    if (lease?.jobId === jobId) {
      return "running";
    }
    const waiting = (stored.get("waiting") as WaitingRef[] | undefined) ?? [];
    if (waiting.some((entry) => entry.jobId === jobId)) {
      return "queued";
    }
    return "unknown";
  }

  private async advance(): Promise<void> {
    const waiting = (await this.ctx.storage.get<WaitingRef[]>("waiting")) ?? [];
    while (waiting.length > 0) {
      const next = waiting.shift() as WaitingRef;
      const params = await this.ctx.storage.get<ExtractionParams>(next.key);
      if (params == null) {
        continue;
      }
      try {
        await this.env.EXTRACTION.create({ id: next.jobId, params });
      } catch {
        // A waiting entry that cannot create must not wedge the queue behind
        // it: drop it and try the next, exactly as a sweep would.
        continue;
      }
      await this.ctx.storage.delete(next.key);
      await this.ctx.storage.put({ waiting, lease: { jobId: next.jobId } });
      await this.ctx.storage.setAlarm(Date.now() + this.env.leaseAlarmMs);
      return;
    }
    await this.ctx.storage.put("waiting", waiting);
    await this.ctx.storage.deleteAlarm();
  }

  async alarm(): Promise<void> {
    const lease = await this.ctx.storage.get<Lease>("lease");
    if (lease == null) {
      return;
    }
    let ended = false;
    try {
      const instance = await this.env.EXTRACTION.get(lease.jobId);
      const status = await instance.status();
      ended = TERMINAL_INSTANCE_STATUSES.has(status.status);
    } catch {
      // An unaddressable instance sweeps like an ended one: the lease
      // cannot be verified, and the queue must move on.
      ended = true;
    }
    if (ended) {
      await this.ctx.storage.delete("lease");
      await this.advance();
      return;
    }
    await this.ctx.storage.setAlarm(Date.now() + this.env.leaseAlarmMs);
  }
}
import { WorkflowEntrypoint, type WorkflowEvent, type WorkflowStep } from "cloudflare:workers";
import { authorMessage, revisionMessage } from "../agents/prompts.ts";
import { parseSettlement, type Settlement } from "../agents/settlement.ts";
import { describeError } from "../errors.ts";
import type { JobStatusBody } from "../http/job-status.ts";
import { domainQueueStub } from "../queue/domain-queue.ts";
import type { Unit } from "../runtime/units.ts";
import { resolveWorld, type WorkflowWorld } from "./world.ts";

export interface ExtractionParams {
  html: string;
  recipe?: string;
  domain: string;
}

type GuardedRun =
  | { outcome: "ok"; title: string; units: Unit[] }
  | { outcome: "invalid"; report: string[] }
  | { outcome: "platform"; failure: string };

async function guardedRun(world: WorkflowWorld, source: string, html: string): Promise<GuardedRun> {
  try {
    const result = await world.runRecipe(source, html);
    if (result.ok) {
      return { outcome: "ok", title: result.title ?? "", units: result.units ?? [] };
    }
    return { outcome: "invalid", report: result.report ?? ["the run failed without a report"] };
  } catch (error) {
    return { outcome: "platform", failure: describeError(error) };
  }
}

interface AttemptOptions {
  kind: "author" | "revision";
  retries: number;
  jobId: string;
  html: string;
  recipe?: string;
  label: string;
  message: (report: string[] | null) => string;
  exhausted: string;
  seedReport?: string[];
}

// One bounded loop for both prompts: every attempt is a fresh conversation
// (the bare job id first, suffixed ids after), the settled script is re-run
// through the runtime, and the failing report feeds the next attempt's
// message.
async function settleRecipe(
  world: WorkflowWorld,
  step: WorkflowStep,
  options: AttemptOptions,
): Promise<JobStatusBody> {
  let report: string[] | null = options.seedReport ?? null;
  for (let attempt = 1; attempt <= 1 + options.retries; attempt += 1) {
    const conversationId = attempt === 1 ? options.jobId : `${options.jobId}-${attempt}`;
    const receipt = await step.do(`${options.label} attempt ${attempt}: dispatch`, () =>
      world.dispatchAgent(options.kind, conversationId, options.message(report), {
        html: options.html,
        recipe: options.recipe,
      }),
    );
    const settlement: Settlement = await step.do(
      `${options.label} attempt ${attempt}: read`,
      async () => {
        try {
          const reply = await world.readAgent(options.kind, conversationId, receipt);
          return parseSettlement(reply.text);
        } catch (error) {
          return { kind: "gave-up", reason: describeError(error) };
        }
      },
    );
    if (settlement.kind === "not-article") {
      return { state: "not_article" };
    }
    if (settlement.kind === "script") {
      const run = await step.do(`${options.label} attempt ${attempt}: run script`, () =>
        guardedRun(world, settlement.source, options.html),
      );
      if (run.outcome === "platform") {
        return { state: "error", error: run.failure };
      }
      if (run.outcome === "ok") {
        return {
          state: "complete",
          title: run.title,
          units: run.units,
          recipe: settlement.source,
        };
      }
      report = run.report;
    }
  }
  return { state: "error", error: options.exhausted };
}

export class ExtractionWorkflow extends WorkflowEntrypoint<Cloudflare.Env, ExtractionParams> {
  async run(event: WorkflowEvent<ExtractionParams>, step: WorkflowStep): Promise<JobStatusBody> {
    const { html, recipe, domain } = event.payload;
    const jobId = event.instanceId;
    const world = resolveWorld(this.env);

    let terminal: JobStatusBody;
    if (recipe != null) {
      const first = await step.do("run provided recipe", () => guardedRun(world, recipe, html));
      if (first.outcome === "platform") {
        terminal = { state: "error", error: first.failure };
      } else if (first.outcome === "ok") {
        terminal = { state: "complete", title: first.title, units: first.units };
      } else {
        terminal = await settleRecipe(world, step, {
          kind: "revision",
          retries: this.env.revisionRetries,
          jobId,
          html,
          recipe,
          label: "revision",
          message: (report) => revisionMessage(domain, report ?? [], recipe),
          exhausted:
            "revision gave up: the recipe still fails the article and the old version stands",
          seedReport: first.report,
        });
      }
    } else {
      terminal = await settleRecipe(world, step, {
        kind: "author",
        retries: this.env.authoringRetries,
        jobId,
        html,
        label: "authoring",
        message: (report) => authorMessage(domain, report),
        exhausted: "authoring gave up: nothing is saved for the domain and the item fails",
      });
    }

    await step.do("release lease", async () => {
      try {
        await domainQueueStub(this.env, domain).release(jobId);
        return { released: true };
      } catch (error) {
        return { released: false, error: describeError(error) };
      }
    });

    return terminal;
  }
}

