export interface WorkflowWorld {
  runRecipe(source: string, html: string): Promise<RecipeRun>;
  dispatchAgent(
    kind: AgentKind,
    conversationId: string,
    message: string,
    initialData: AgentInitialData,
  ): Promise<AgentDispatchReceipt>;
  readAgent(
    kind: AgentKind,
    conversationId: string,
